using MediDesk.Business.Interfaces;using MediDesk.Common.Contracts.Administration;using MediDesk.Common.Contracts.Catalog;namespace MediDesk.Business.Services;public sealed class StoreService(IStoreRepository r):IStoreService{public Task<PagedResponse<StoreDto>>GetPageAsync(StoreQuery q,CancellationToken ct)=>r.GetPageAsync(q with{Search=q.Search?.Trim(),Page=Math.Max(1,q.Page),PageSize=Math.Clamp(q.PageSize,1,200)},ct);public Task<StoreDto>CreateAsync(CreateStoreRequest x,long u,CancellationToken ct)=>r.CreateAsync(x with{Name=x.Name.Trim(),Phone=x.Phone.Trim(),City=x.City.Trim(),State=x.State.Trim()},u,ct);}

